def getMemberNames(self):
    assert self.isCollection
    childlist = set()
    l = len(self.path)
    for f in self.provider.files:
        if f.startswith(self.path):
            p = f[l:]
            if '/' in p:
                p = p.split('/')[0]
            childlist.add(p)
        else:
            if childlist:
                break
    return list(childlist)
